import 'package:fpdart/fpdart.dart';

import '../../../../core/failure/failure.dart';
import '../entities/entries_page.dart';
import '../entities/entry.dart';

/// The port later epics extend (Code Map) — `features/capture/` depends on
/// this abstract class only, never `entries/data` or `entries/presentation`
/// (RNF06).
abstract class EntriesRepository {
  /// Posts to `entries-create` (`ApiClient.post`, via
  /// `EntriesRemoteDataSource`) and, on success, writes the entry through
  /// to the `entries` Hive box before returning `Right` (Boundaries) — a
  /// caller that only reads the returned [Entry] never needs to touch the
  /// box itself. Every [Failure] — including
  /// [Failure.networkOffline] — is returned as `Left`, unmapped and
  /// un-retried; the caller decides what to do with it (RNF09).
  Future<Either<Failure, Entry>> create({
    required String content,
    required EntrySource source,
    int? mediaDurationSeconds,
  });

  /// Calls `entries-list` (`ApiClient.get`, via
  /// `EntriesRemoteDataSource`), newest-first by `occurredAt` — server
  /// behavior assumed, undocumented (Code Map, decided per AGENTS.md
  /// policy: "where `docs/input/` is silent... decide and proceed").
  ///
  /// On [Failure.networkOffline]/[Failure.networkTimeout] specifically,
  /// falls back to a full dump of the `entries` Hive box, sorted
  /// `occurredAt` desc, with `EntriesPage.nextCursor: null` (Boundaries) —
  /// every *other* [Failure] (e.g. [Failure.authExpired]) propagates as
  /// `Left`, unmapped (RNF09).
  ///
  /// A successful page persists every item to the `entries` Hive box
  /// *before* returning `Right` — same "persist then return" ordering
  /// [create] already uses.
  Future<Either<Failure, EntriesPage>> list({String? cursor, int limit = 20});
}

import 'package:fpdart/fpdart.dart';

import '../../../../core/failure/failure.dart';
import '../../../../core/network/api_client.dart';
import '../../domain/entities/entry.dart';
import '../models/entry_dto.dart';

/// The entries feature's one write call so far (`entries-create`) — posts
/// via the shared `ApiClient`, mirroring `account_remote_data_source.dart`'s
/// pattern.
class EntriesRemoteDataSource {
  EntriesRemoteDataSource(this._apiClient);

  final ApiClient _apiClient;

  /// Sends `{content, source}` plus `mediaDurationSeconds` only when
  /// non-null (spec-3-2's `source: audio` entries) — this story still
  /// never passes `chatMessageId`/`occurredAt` (Boundaries: no `Entry`
  /// field beyond the modeled 9; those two are optional in the contract
  /// and belong to later stories/epics).
  Future<Either<Failure, EntryDto>> create({
    required String content,
    required EntrySource source,
    int? mediaDurationSeconds,
  }) async {
    final result = await _apiClient.post(
      'entries-create',
      data: {
        'content': content,
        'source': source.name,
        'mediaDurationSeconds': ?mediaDurationSeconds,
      },
    );
    return result.flatMap((json) {
      try {
        final data = json['data'] as Map<String, dynamic>;
        return right(EntryDto.fromJson(data));
      } catch (error) {
        // A 200 response that doesn't match the expected shape is a
        // client-side parse failure, never a backend-sent code — maps to
        // the local-only `malformedResponse` (RNF09: no exception escapes
        // unmapped).
        return left(Failure.malformedResponse(message: error.toString()));
      }
    });
  }

  /// Calls `entries-list` (`ApiClient.get`) with `limit` always sent, and
  /// `cursor` only when non-null (spec-4-1's own convention for an
  /// optional-in-the-contract query parameter, mirroring [create]'s own
  /// `mediaDurationSeconds` handling). Returns the raw page as a record —
  /// no dedicated DTO wrapper type, since `EntriesRepositoryImpl.list()` is
  /// this record's only reader.
  Future<Either<Failure, ({List<EntryDto> items, String? nextCursor})>> list({
    String? cursor,
    int limit = 20,
  }) async {
    final result = await _apiClient.get(
      'entries-list',
      queryParameters: {'limit': limit, 'cursor': ?cursor},
    );
    return result.flatMap((json) {
      try {
        final data = json['data'] as List<dynamic>;
        final items = data
            .map((item) => EntryDto.fromJson(item as Map<String, dynamic>))
            .toList();
        final meta = json['meta'] as Map<String, dynamic>;
        final nextCursor = meta['nextCursor'] as String?;
        return right((items: items, nextCursor: nextCursor));
      } catch (error) {
        // Same client-side-parse-failure rationale as `create()` above.
        return left(Failure.malformedResponse(message: error.toString()));
      }
    });
  }
}

// The constructor keeps public named params (`remoteDataSource`,
// `entriesBox`) distinct from the private fields they initialize, matching
// `account_settings_repository_impl.dart`'s documented convention.
// ignore_for_file: prefer_initializing_formals
import 'package:fpdart/fpdart.dart';
import 'package:hive_ce/hive_ce.dart';

import '../../../../core/failure/failure.dart';
import '../../domain/entities/entries_page.dart';
import '../../domain/entities/entry.dart';
import '../../domain/repositories/entries_repository.dart';
import '../datasources/entries_remote_data_source.dart';
import '../models/entry_dto.dart';

/// On success, writes the entry through to the `entries` Hive box (`Box
/// <Map>`, keyed by id, raw `EntryDto.toJson()` — Design Notes) *before*
/// returning `right(...)`, same "persist then return" ordering
/// `AuthRepositoryImpl._authenticate` already uses for its own
/// post-success side effect.
class EntriesRepositoryImpl implements EntriesRepository {
  EntriesRepositoryImpl({
    required EntriesRemoteDataSource remoteDataSource,
    required Box<Map> entriesBox,
  }) : _remoteDataSource = remoteDataSource,
       _entriesBox = entriesBox;

  final EntriesRemoteDataSource _remoteDataSource;
  final Box<Map> _entriesBox;

  @override
  Future<Either<Failure, Entry>> create({
    required String content,
    required EntrySource source,
    int? mediaDurationSeconds,
  }) async {
    final result = await _remoteDataSource.create(
      content: content,
      source: source,
      mediaDurationSeconds: mediaDurationSeconds,
    );
    return result.match((failure) async => left(failure), (dto) async {
      // A thrown Hive/disk exception must never escape unmapped (RNF09) —
      // same rationale/fallback `AuthRepositoryImpl` already uses for its
      // own local-persistence step.
      try {
        await _entriesBox.put(dto.id, dto.toJson());
      } catch (error) {
        return left(Failure.malformedResponse(message: error.toString()));
      }
      return right(_toEntry(dto));
    });
  }

  @override
  Future<Either<Failure, EntriesPage>> list({
    String? cursor,
    int limit = 20,
  }) async {
    final result = await _remoteDataSource.list(cursor: cursor, limit: limit);
    return result.match(
      (failure) async {
        // Boundaries/Design Notes: the Hive-cache fallback is scoped to
        // `cursor == null` (the first/fresh page) only — a paginated
        // continuation (`cursor != null`) that fails with
        // `networkOffline`/`networkTimeout` propagates as `Left` like any
        // other pagination failure instead, so `MeusRegistrosCubit`'s own
        // `loadMoreFailed`/retry path handles it uniformly rather than a
        // full unrelated cache dump silently replacing the in-progress
        // paginated list (and breaking its newest-first ordering).
        if (cursor == null &&
            (failure is NetworkOffline || failure is NetworkTimeout)) {
          return _offlineFallback();
        }
        return left(failure);
      },
      (page) async {
        try {
          await _entriesBox.putAll({
            for (final dto in page.items) dto.id: dto.toJson(),
          });
        } catch (error) {
          // Same RNF09 rationale as `create()`'s own Hive-write guard — a
          // thrown Hive/disk exception must never escape unmapped.
          return left(Failure.malformedResponse(message: error.toString()));
        }
        return right(
          EntriesPage(
            items: page.items.map(_toEntry).toList(),
            nextCursor: page.nextCursor,
          ),
        );
      },
    );
  }

  /// The offline/timeout fallback (Boundaries): a full `entries` Hive box
  /// dump, sorted `occurredAt` desc, always `nextCursor: null` — a cached
  /// dump has no further page to request. A corrupt cached entry (should
  /// never happen — every entry here was written by [create]/[list]
  /// themselves) maps to `Left(malformedResponse)` rather than throwing
  /// (RNF09), same guard `create()`'s own Hive write already has.
  Either<Failure, EntriesPage> _offlineFallback() {
    try {
      final entries =
          _entriesBox.values
              .map(
                (json) => _toEntry(
                  EntryDto.fromJson(Map<String, dynamic>.from(json)),
                ),
              )
              .toList()
            ..sort(
              (a, b) =>
                  DateTime.parse(b.occurredAt)
                      .compareTo(DateTime.parse(a.occurredAt)),
            );
      return right(EntriesPage(items: entries, nextCursor: null));
    } catch (error) {
      return left(Failure.malformedResponse(message: error.toString()));
    }
  }

  Entry _toEntry(EntryDto dto) => Entry(
    id: dto.id,
    content: dto.content,
    source: dto.source,
    chatMessageId: dto.chatMessageId,
    occurredAt: dto.occurredAt,
    serverRevision: dto.serverRevision,
    createdAt: dto.createdAt,
    updatedAt: dto.updatedAt,
    mediaDurationSeconds: dto.mediaDurationSeconds,
  );
}

