  5	/// A single `EntryRecordCard`'s own sync badge (AD-10) — exactly the 3
  6	/// states `docs/input/backend/sync-badge.md` names, never a 4th: the
  7	/// server exposes no sync field of its own, so these 3 are the complete
  8	/// set this app ever needs to render. Sealed, with `const factory`
  9	/// constructors on the base class (mirrors `Failure`'s own shape, minus
 10	/// the `freezed` codegen — no `==`/`copyWith` machinery is needed here
 11	/// beyond the hand-rolled equality each subclass already carries) so call
 12	/// sites read as `SyncBadgeState.synchronizing()` rather than naming each
 13	/// subclass directly.
 14	sealed class SyncBadgeState {
 15	  const SyncBadgeState();
 16	
 17	  const factory SyncBadgeState.synchronizing() = SyncBadgeSynchronizing;
 18	
 19	  const factory SyncBadgeState.synchronized() = SyncBadgeSynchronized;
 20	
 21	  const factory SyncBadgeState.error(Failure failure) = SyncBadgeError;
 22	}
