 42	  const SyncBadgeSynchronized();
 43	
 44	  @override
 45	  bool operator ==(Object other) => other is SyncBadgeSynchronized;
 46	
 47	  @override
 48	  int get hashCode => (SyncBadgeSynchronized).hashCode;
 49	
 50	  @override
 51	  String toString() => 'SyncBadgeSynchronized()';
 52	}
