 54	/// "Synchronization error" (red) — the write was attempted and failed,
 55	/// never yet reconciled. [failure] is kept so the badge's own tap handler
 56	/// (`SyncBadge`) can read [Failure.retryable]/[Failure.message] directly,
 57	/// per the Boundaries' "Tap on error badge" rule.
 58	class SyncBadgeError extends SyncBadgeState {
 59	  const SyncBadgeError(this.failure);
 60	
 61	  final Failure failure;
 62	
 63	  @override
 64	  bool operator ==(Object other) =>
 65	      identical(this, other) ||
 66	      (other is SyncBadgeError && other.failure == failure);
