 58	class MeusRegistrosLoaded extends MeusRegistrosState {
 59	  const MeusRegistrosLoaded({
 60	    required this.entries,
 61	    required this.nextCursor,
 62	    this.isLoadingMore = false,
 63	    this.loadMoreFailed = false,
 64	    this.pendingWrites = const [],
