172	Entry _placeholderEntryFor(PendingEntryWrite pending) {
173	  final startedAtIso = pending.startedAt.toIso8601String();
174	  return Entry(
175	    id: pending.tempId,
176	    content: pending.content,
177	    source: pending.source,
178	    chatMessageId: null,
179	    occurredAt: startedAtIso,
180	    serverRevision: 0,
181	    createdAt: startedAtIso,
182	    updatedAt: startedAtIso,
183	    mediaDurationSeconds: pending.mediaDurationSeconds,
184	  );
185	}
186	
187	bool _listEquals<T>(List<T> a, List<T> b) {
188	  if (a.length != b.length) {
189	    return false;
190	  }
191	  for (var i = 0; i < a.length; i++) {
192	    if (a[i] != b[i]) {
193	      return false;
194	    }
195	  }
196	  return true;
197	}

