 46	class _MeusRegistrosScreenState extends State<MeusRegistrosScreen> {
 47	  // RNF01: no loading UI below 300ms — same threshold/`Timer` pattern as
 48	  // `BootSplashScreen`.
 49	  static const _skeletonThreshold = Duration(milliseconds: 300);
 50	
 51	  final ScrollController _scrollController = ScrollController();
 52	  Timer? _skeletonTimer;
 53	  bool _showSkeleton = false;
 54	
 55	  @override
 56	  void initState() {
 57	    super.initState();
 58	    widget.cubit.loadFirstPage();
 59	    _skeletonTimer = Timer(_skeletonThreshold, () {
 60	      if (mounted) {
 61	        setState(() => _showSkeleton = true);
 62	      }
 63	    });
 64	    _scrollController.addListener(_onScroll);
 65	  }
 66	
 67	  @override
 68	  void dispose() {
 69	    _skeletonTimer?.cancel();
 70	    _scrollController
 71	      ..removeListener(_onScroll)
 72	      ..dispose();
 73	    super.dispose();
 74	  }
 75	
 76	  void _onScroll() {
 77	    if (!_scrollController.hasClients) {
 78	      return;
 79	    }
 80	    final position = _scrollController.position;
 81	    // Pre-fetches a little before the exact end (reusing `spacing2xl`
 82	    // purely as a scroll-distance buffer, not a new literal) for a
 83	    // smoother scroll-pagination feel; `loadMore()` itself is a no-op once
 84	    // there's no further page or a call is already in flight.
 85	    if (position.pixels >= position.maxScrollExtent - DesignTokens.spacing2xl) {
 86	      widget.cubit.loadMore();
 87	    }
 88	  }
